import backtrader as bt


class Strategy(bt.Strategy):
    params = (
        ("macd_fast", 12),
        ("macd_slow", 26),
        ("macd_signal", 9),
        ("atr_period", 14),
        ("risk_fraction", 0.01),
        ("stop_fraction", 0.02),
    )

    def __init__(self):
        self.macd = bt.indicators.MACD(
            self.data.close,
            period_me1=self.p.macd_fast,
            period_me2=self.p.macd_slow,
            period_signal=self.p.macd_signal,
        )
        self.macd_cross = bt.indicators.CrossOver(self.macd.macd, self.macd.signal)
        self.atr = bt.indicators.ATR(self.data, period=self.p.atr_period)
        self.order = None
        self.stop_order = None
        self.entry_price = None

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order.status == order.Completed:
            if order is self.order:
                self.order = None
                if self.position:
                    self.entry_price = order.executed.price
                    if self.position.size > 0:
                        stop_price = self.entry_price * (1.0 - self.p.stop_fraction)
                        self.stop_order = self.sell(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=stop_price,
                        )
                    else:
                        stop_price = self.entry_price * (1.0 + self.p.stop_fraction)
                        self.stop_order = self.buy(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=stop_price,
                        )
                else:
                    self.entry_price = None
            elif order is self.stop_order:
                self.stop_order = None
                self.entry_price = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order:
            return

        if self.position:
            opposite_signal = (
                self.position.size > 0 and self.macd_cross[0] < 0
            ) or (
                self.position.size < 0 and self.macd_cross[0] > 0
            )
            if opposite_signal:
                if self.stop_order:
                    self.cancel(self.stop_order)
                    self.stop_order = None
                self.order = self.close()
            return

        if self.stop_order:
            return

        atr_value = self.atr[0]
        if not atr_value or atr_value <= 0.0:
            return
        risk_amount = self.broker.getvalue() * self.p.risk_fraction
        size = int(risk_amount / atr_value)
        if size <= 0:
            return

        if self.macd_cross[0] > 0:
            self.order = self.buy(size=size)
        elif self.macd_cross[0] < 0:
            self.order = self.sell(size=size)
